<?php
declare(strict_types=1);
function page_home(): void {
 echo '<section class="portal-section" aria-labelledby="portal-heading"><div class="section-head"><div><p class="eyebrow">YOUR PORTAL</p><h2 id="portal-heading">Choose your workspace</h2><p class="muted">Select your role to access your dashboard.</p></div></div><div class="portal-grid">';
 foreach(portal_options() as $role=>[$title,$description,$ic])echo '<article class="card portal-card"><span class="portal-icon" aria-hidden="true">'.icon($ic).'</span><h3>'.e($title).'</h3><p>'.e($description).'</p><a class="button secondary" aria-label="Access '.e($title).'" href="'.e(url('login',['portal'=>$role])).'">Access Portal '.icon('arrow').'</a></article>';
 echo '</div></section>';

 echo '<section class="hero"><div><span class="hero-tag"><span class="status-dot"></span> CONNECTED COMMUNITIES. COORDINATED RESPONSE.</span><h1>Report disasters.<br><em>Find support in your area.</em></h1><p>Report an incident, find a safe place, and connect with the people coordinating support across Sri Lanka.</p><div class="hero-actions"><a class="button light" href="'.url('new-report').'">Report an incident '.icon('arrow').'</a><a class="button outline-light" href="'.url('map').'">Explore situation map</a></div><small>Community reports are reviewed before public display.</small></div><figure class="hero-art">'.visual_image('community','hero-photo',true,'(max-width: 600px) calc(100vw - 80px), (max-width: 900px) 40vw, 440px').'</figure></section>';
 metrics([['Verified active incidents',scalar("SELECT COUNT(*) FROM reports WHERE status='verified'"),'Reviewed by authorities','reports'],['Active alerts',scalar('SELECT COUNT(*) FROM alerts WHERE active=1 AND (expires_at IS NULL OR expires_at>NOW())'),'Published by authorized staff','alerts'],['Open facilities',scalar("SELECT COUNT(*) FROM facilities WHERE status='open'"),'Shelters and hospitals','facilities'],['Available volunteers',scalar("SELECT COUNT(*) FROM volunteers v JOIN users u ON u.id=v.user_id WHERE availability='available' AND u.active=1"),'Ready for approved assignments','volunteers']]);
 echo '<div class="section-head"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>Reports and support services</h2></div></div><div class="quick-grid">';foreach([['reports','Report a disaster','Tell us what happened so an authority can review it.','new-report'],['facilities','Find a safe facility','Explore shelters, hospitals and available services.','facilities'],['assistance','Request assistance','Submit a request and track its progress.','assistance'],['volunteers','Make a difference','Register your skills and receive assignments.','volunteers']] as [$ic,$title,$desc,$p])echo '<a class="quick-card card" href="'.url($p).'">'.icon($ic).'<h3>'.$title.'</h3><p>'.$desc.'</p><span>Get started '.icon('arrow').'</span></a>';echo '</div><div class="section-head"><h2>Latest verified incidents</h2><a class="text-link" href="'.url('map').'">View the map →</a></div><section class="card">';report_list(all("SELECT r.*,t.name type FROM reports r JOIN disaster_types t ON t.id=r.type_id WHERE r.status='verified' ORDER BY r.created_at DESC LIMIT 5"));echo '</section><p class="disclaimer">We built SafeNation to help people report incidents and coordinate support. Our system does not replace official emergency services or government warnings.</p>';
}
function page_auth(string $p): void {
 $reg=$p==='register';$portal=$reg?'':selected_portal();
 if($portal&&user()) {
  need_login();
  if(user()['role']===$portal)go('dashboard');
  http_response_code(403);
  heading('PORTAL ACCESS',portal_options()[$portal][0],'Your current account has a different role. Sign out to use an account assigned to this portal.');
  echo '<section class="card padded"><a class="button secondary" href="'.url('dashboard').'">Go to my dashboard</a>';
  start_form('logout','','compact');end_form('Sign out');echo '</section>';return;
 }
 heading('COMMUNITY ACCESS',$reg?'Create your SafeNation account':($portal?portal_options()[$portal][0]:'Welcome back.'),$reg?'Create a citizen or volunteer account. Operational roles are assigned by administrators.':'Sign in to report incidents, track support and coordinate your work.');echo '<div class="auth-layout">';start_form($reg?'register':'login',$reg?'Create your account':'Sign in','auth-form');
 if($portal)echo '<input type="hidden" name="portal" value="'.e($portal).'"><p class="hint">Sign in with an account assigned to this portal. <a href="'.url('home').'">Choose another portal</a> or <a href="'.url('login').'">use standard sign in</a>.</p>';
 if($reg){field('name','Full name','text','',true,'maxlength="100"');field('area','Area / district','text','',true,'maxlength="100"');field('phone','Phone (optional)','tel','',false,'maxlength="30"');select('role','I am joining as',['citizen'=>'Citizen','volunteer'=>'Volunteer']);}
 field('email','Email address','email','',true,'autocomplete="email" maxlength="190"');field('password','Password','password','',true,'autocomplete="'.($reg?'new-password':'current-password').'" '.($reg?'minlength="12" maxlength="72"':''));
 if($reg){field('confirm_password','Confirm password','password','',true,'autocomplete="new-password" minlength="12" maxlength="72"');echo '<p class="hint">Use at least 12 characters. Your password is stored as a secure hash.</p><label class="check"><input type="checkbox" name="consent" required> I understand that my profile, report location and request details are stored for coordination and visible to authorized staff.</label>';}
 end_form($reg?'Create account':'Sign in');echo '<div class="auth-aside">'.icon('shield').'<h2>Report incidents.<br>Track your requests.</h2><p>Authorities review incident reports before they appear publicly. You can follow request updates and assignments from your dashboard.</p><a class="text-link" href="'.url($reg?'login':'register').'">'.($reg?'Already registered? Sign in':'New here? Create an account').' →</a></div></div>';
}
function page_dashboard(): void {
 need_login();$u=user();heading('YOUR WORKSPACE','Hello, '.explode(' ',$u['name'])[0].'.','View your reports, requests, assignments and latest updates.','<a class="button" href="'.url('new-report').'">Report an incident '.icon('arrow').'</a>');
 if(can('respond'))metrics([['Awaiting verification',scalar("SELECT COUNT(*) FROM reports WHERE status='pending'"),'Community submissions','reports'],['High / critical incidents',scalar("SELECT COUNT(*) FROM reports WHERE status='verified' AND severity IN ('High','Critical')"),'Priorities reviewed by authorities','alerts'],['Open assistance requests',scalar("SELECT COUNT(*) FROM assistance_requests WHERE status NOT IN ('fulfilled','cancelled')"),'Requests needing follow-up','assistance'],['Unread notifications',scalar('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL',[$u['id']]),'Updates for your account','notifications']]);
 else metrics([['My incident reports',scalar('SELECT COUNT(*) FROM reports WHERE user_id=?',[$u['id']]),'Submitted by you','reports'],['My open requests',scalar("SELECT COUNT(*) FROM assistance_requests WHERE user_id=? AND status NOT IN ('fulfilled','cancelled')",[$u['id']]),'Support in progress','assistance'],['My assignments',scalar("SELECT COUNT(*) FROM volunteer_assignments WHERE volunteer_id=? AND status NOT IN ('completed','declined','cancelled')",[$u['id']]),'Approved volunteer tasks','volunteers'],['Unread notifications',scalar('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL',[$u['id']]),'Status updates','notifications']]);
 echo '<div class="two-columns"><section class="card"><div class="card-head"><h2>'.(can('coordinate')?'Review queue':'My recent reports').'</h2><a href="'.url('reports').'">View all →</a></div>';
 $where=can('coordinate')?"r.status='pending'":'r.user_id=?';report_list(all('SELECT r.*,t.name type FROM reports r JOIN disaster_types t ON t.id=r.type_id WHERE '.$where.' ORDER BY r.created_at DESC LIMIT 6',can('coordinate')?[]:[$u['id']]));echo '</section><section class="card padded"><h2>Latest updates</h2>';$ns=all('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5',[$u['id']]);if(!$ns)empty_state('You are up to date','Notifications will appear here as your work progresses.');foreach($ns as $n)echo '<a class="update-item" href="'.e($n['link']).'"><strong>'.e($n['title']).'</strong><p>'.e(mb_strimwidth($n['message'],0,140,'…')).'</p><small>'.e($n['created_at']).'</small></a>';echo '</section></div>';
 if($u['role']==='facility_manager')echo '<a class="button secondary" href="'.url('facilities').'">Manage assigned facilities</a>';
}
function page_reports(): void {
 need_login();heading('INCIDENT MANAGEMENT',can('respond')?'Incident reports':'My incident reports','Search incident reports and follow their review and response history.','<a class="button" href="'.url('new-report').'">New incident report</a>');
 $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$severity=(string)($_GET['severity']??'');$type=(int)($_GET['type_id']??0);$conds=[];$args=[];
 if(!can('respond')){$conds[]='r.user_id=?';$args[]=user()['id'];}elseif(!can('coordinate'))$conds[]="r.status IN ('verified','resolved')";
 if($q!==''){$conds[]='(r.title LIKE ? OR r.area LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($status){$conds[]='r.status=?';$args[]=$status;}if($severity){$conds[]='r.severity=?';$args[]=$severity;}if($type){$conds[]='r.type_id=?';$args[]=$type;}
 echo '<form class="filters" method="get"><input type="hidden" name="page" value="reports">';field('q','Search title or area','search',$q,false);select('status','Status',[''=>'All statuses','pending'=>'Pending','verified'=>'Verified','rejected'=>'Rejected','duplicate'=>'Duplicate','merged'=>'Merged','resolved'=>'Resolved'],$status);select('severity','Severity',[''=>'All severities','Low'=>'Low','Medium'=>'Medium','High'=>'High','Critical'=>'Critical'],$severity);select('type_id','Category',[0=>'All categories']+array_column(types(),'name','id'),$type);echo '<button class="button secondary">Apply filters</button></form>';
 $where=$conds?' WHERE '.implode(' AND ',$conds):'';$total=(int)scalar('SELECT COUNT(*) FROM reports r'.$where,$args);$offset=(max(1,(int)($_GET['p']??1))-1)*15;
 echo '<section class="card">';report_list(all('SELECT r.*,t.name type FROM reports r JOIN disaster_types t ON t.id=r.type_id'.$where.' ORDER BY FIELD(r.severity,\'Critical\',\'High\',\'Medium\',\'Low\'),r.created_at DESC LIMIT 15 OFFSET '.$offset,$args));echo '</section>';pager($total,15,'reports',['q'=>$q,'status'=>$status,'severity'=>$severity,'type_id'=>$type]);
}
function page_new_report(): void {
 need_login();heading('COMMUNITY REPORTING','Report an incident','We send your report to an authority for review. It stays private until it is verified.');start_form('report','Incident details');echo '<div class="form-grid">';field('title','Short incident title','text','',true,'minlength="5" maxlength="150"');type_select();field('occurred_at','When did it happen?','datetime-local',date('Y-m-d\TH:i'));echo '</div>';textarea('description','Describe what you observed','',20);location_fields();echo '<div class="form-grid">';field('affected_people','Estimated people affected','number',0,true,'min="0" max="1000000" step="1"');select('damage','Observed damage',['none'=>'No damage reported','minor'=>'Minor','moderate'=>'Moderate','severe'=>'Severe']);echo '</div><div class="notice"><strong>AI severity analysis and authority review</strong><p>Our system uses fixed rules to suggest a severity level from the details you provide. An authority reviews the suggestion. It does not issue warnings or dispatch responders automatically.</p></div>';end_form('Submit report for review');
}
function page_report(): void {
 $id=(int)($_GET['id']??0);$r=one('SELECT r.*,t.name type,u.name reporter FROM reports r JOIN disaster_types t ON t.id=r.type_id JOIN users u ON u.id=r.user_id WHERE r.id=?',[$id]);if(!$r)throw new RuntimeException('Incident report not found.');$owner=user()&&(int)user()['id']===(int)$r['user_id'];if(!in_array($r['status'],['verified','resolved'],true)&&!$owner&&!can('coordinate')) {http_response_code(403);throw new RuntimeException('This unverified report is private.');}
 heading('INCIDENT #'.$id,$r['title'],$r['type'].' · '.$r['area'].' · Reported '.date('d M Y, H:i',strtotime($r['created_at'])));echo '<div class="two-columns"><article class="card padded">'.incident_visual($r['type']).'<div class="badge-row">'.badge($r['status']).badge($r['severity']).badge($r['response_status']).'</div><h2>Incident details</h2><p class="preserve">'.e($r['description']).'</p><dl class="detail-grid"><div><dt>Location</dt><dd>'.e($r['area']).'</dd></div><div><dt>Address / landmark</dt><dd>'.e($r['address']?:'Not recorded').'</dd></div><div><dt>Coordinates</dt><dd>'.e($r['latitude']).', '.e($r['longitude']).'</dd></div><div><dt>Occurred</dt><dd>'.e($r['occurred_at']).'</dd></div><div><dt>Reported people affected</dt><dd>'.e($r['affected_people']).'</dd></div><div><dt>Reported damage</dt><dd>'.e(ucfirst($r['damage'])).'</dd></div></dl>';
 if($r['duplicate_of'])echo '<p>Canonical incident: <a href="'.url('report',['id'=>$r['duplicate_of']]).'">#'.e($r['duplicate_of']).'</a></p>';
 if($owner||can('respond'))echo '<div class="notice"><strong>Preliminary recommendation: '.e($r['ai_severity']).'</strong><p>'.e($r['ai_reason']).'</p><small>This suggestion uses fixed rules, not a trained prediction model. It has not been validated for emergency decisions. Authorities can change the reviewed severity.</small></div>';
 echo '</article><aside class="card padded"><h2>Verification timeline</h2>';$reviews=all('SELECT v.*,u.name reviewer FROM report_reviews v JOIN users u ON u.id=v.reviewer_id WHERE report_id=? ORDER BY v.id DESC',[$id]);if(!$reviews)echo '<p class="muted">Awaiting authority review.</p>';foreach($reviews as $v)echo '<div class="timeline-item">'.badge($v['status']).'<strong>'.e($v['reviewer']).'</strong><p>'.e($v['note']).'</p><small>'.e($v['created_at']).' · '.e($v['severity']).'</small></div>';echo '</aside></div>';
 if(can('coordinate')) {$dups=duplicates($r);echo '<div class="two-columns">';start_form('review','Authority review');echo '<input type="hidden" name="id" value="'.$id.'"><div class="form-grid">';select('status','Decision',array_combine(['pending','verified','rejected','duplicate','merged','resolved'],['Pending','Verified','Rejected','Duplicate','Merged into canonical incident','Resolved']),$r['status']);severity_select($r['severity']);echo '</div>';select('duplicate_of','Canonical report (for duplicate / merge)',[0=>'No canonical report']+array_column(all("SELECT id,CONCAT('#',id,' · ',title) label FROM reports WHERE id<>? AND status IN ('verified','resolved') ORDER BY id DESC",[$id]),'label','id'),$r['duplicate_of']??0);textarea('note','Reason for the decision','',5,3000);echo '<p class="hint">Merging links the complete source report and its history to the canonical incident. It keeps one public marker without deleting evidence.</p>';end_form('Save review decision');echo '<section class="card padded"><h2>Possible duplicate reports</h2><p class="muted">Same category, within 5 km and 48 hours, with at least 20% text similarity. Review before linking.</p>';if(!$dups)empty_state('No candidates found','Duplicate matching is advisory.');foreach($dups as $d)echo '<div class="update-item"><a href="'.url('report',['id'=>$d['id']]).'"><strong>#'.e($d['id']).' · '.e($d['title']).'</strong></a><p>'.e(round($d['distance'],2)).' km · '.e(round($d['similarity'])).'% similarity</p></div>';echo '</section></div>';}
 if(can('coordinate')){echo '<details><summary>Correct incident details</summary>';start_form('report_edit','Update incident details');echo '<input type="hidden" name="id" value="'.$id.'"><div class="form-grid">';field('title','Incident title','text',$r['title'],true,'minlength="5" maxlength="150"');type_select($r['type_id']);field('occurred_at','Occurred at','datetime-local',date('Y-m-d\TH:i',strtotime($r['occurred_at'])));echo '</div>';textarea('description','Description',$r['description'],20);location_fields($r);echo '<div class="form-grid">';field('affected_people','People affected','number',$r['affected_people'],true,'min="0" max="1000000"');select('damage','Observed damage',['none'=>'None','minor'=>'Minor','moderate'=>'Moderate','severe'=>'Severe'],$r['damage']);echo '</div>';textarea('note','Reason for the correction','',5,3000);end_form('Save incident corrections');echo '</details>';}
 if(can('respond')&&$r['status']==='verified'){start_form('response','Response coordination');echo '<input type="hidden" name="id" value="'.$id.'">';select('response_status','Response status',['monitoring'=>'Monitoring','dispatched'=>'Dispatched','on_scene'=>'On scene','contained'=>'Contained'],$r['response_status']);textarea('note','Response update','',5,3000);end_form('Update response status');}
}
function page_alerts(): void {
 heading('VERIFIED COMMUNICATION','Emergency alerts','Published by authorized staff. Expired and archived communications remain in history.');$history=isset($_GET['history']);echo '<div class="tabs"><a class="'.(!$history?'selected':'').'" href="'.url('alerts').'">Active alerts</a><a class="'.($history?'selected':'').'" href="'.url('alerts',['history'=>1]).'">Alert history</a></div>';
 $where=$history?'1=1':'a.active=1 AND (a.expires_at IS NULL OR a.expires_at>NOW())';$count=(int)scalar('SELECT COUNT(*) FROM alerts a WHERE '.$where);$offset=(max(1,(int)($_GET['p']??1))-1)*12;$rows=all('SELECT a.*,t.name type,u.name author FROM alerts a JOIN disaster_types t ON t.id=a.type_id JOIN users u ON u.id=a.author_id WHERE '.$where.' ORDER BY a.published_at DESC LIMIT 12 OFFSET '.$offset);
 echo '<div class="alert-grid">';if(!$rows)empty_state('No active alerts','There are no published alerts in the selected view.');foreach($rows as $a){echo '<article class="card alert-card '.e(strtolower($a['severity'])).'">'.incident_visual($a['type'],'alert-visual').'<div class="badge-row">'.badge($a['severity']).'<span class="muted">'.e($a['type']).' · '.e($a['area']).'</span></div><h2>'.e($a['title']).'</h2><p class="preserve">'.e($a['message']).'</p><small>Published '.e($a['published_at']).' by '.e($a['author']).'<br>Expiry: '.e($a['expires_at']??'No scheduled expiry').($a['active']?'':' · Archived').'</small>';if(can('coordinate')&&$a['active']){echo '<form method="post" class="inline">';token();echo '<input type="hidden" name="action" value="archive_alert"><input type="hidden" name="id" value="'.e($a['id']).'"><button class="text-button">Archive alert</button></form>';}echo '</article>';}echo '</div>';pager($count,12,'alerts',$history?['history'=>1]:[]);
 if(can('coordinate')){start_form('alert','Publish an alert');echo '<div class="form-grid">';field('title','Alert title','text','',true,'minlength="5" maxlength="150"');type_select();field('area','Affected area','text','',true,'maxlength="100"');severity_select();field('expires_at','Expiry (optional)','datetime-local','',false);echo '</div>';textarea('message','Alert message','',20);end_form('Publish and notify users');}
}
